import jax
import jax.numpy as np
import collections

class F(collections.namedtuple("F", ["a"])):
  def __call__(self, x):
    return jax.nn.relu(self.a) * x

@jax.jit
def g(f, x):
  return f(x)

jax.grad(F(2.0))(0.)  # works, returns DeviceArray(2., dtype=float32)
jax.grad(g, argnums=(1,))(F(2.0), 0.)  # AssertionError
